                  ${schulhundModule === 'schulhund' 
                    ? 'bg-[#0B79D0] text-white border-[#0B79D0] ring-4 ring-[#0B79D0]/30' 
                    : 'bg-blue-50 text-blue-800 border-blue-200 hover:bg-blue-100 hover:border-blue-400'
