import React, { useState } from 'react';
import { Question } from '../types';
import ConfirmationModal from './ConfirmationModal';

interface QuizProps {
  questions: Question[];
  userAnswers: number[][];
  onAnswerSelect: (questionIndex: number, answerIndex: number) => void;
  onSubmit: () => void;
}

const Quiz: React.FC<QuizProps> = ({ questions, userAnswers, onAnswerSelect, onSubmit }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [isConfirmationModalOpen, setIsConfirmationModalOpen] = useState(false);

  const handleNext = () => {
    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    }
  };

  const handlePrev = () => {
    if (currentQuestionIndex > 0) {
      // FIX: Decrement the index to go to the previous question.
      setCurrentQuestionIndex(currentQuestionIndex - 1);
    }
  };

  const handleSubmitRequest = () => {
    setIsConfirmationModalOpen(true);
  };

  const handleConfirmSubmit = () => {
    setIsConfirmationModalOpen(false);
    onSubmit();
  };

  const currentQuestion = questions[currentQuestionIndex];
  const selectedAnswers = userAnswers[currentQuestionIndex] || [];

  const getTypeBadgeClasses = (type?: string | null): string => {
    const baseClasses = "text-xs font-medium px-2.5 py-0.5 rounded-full ml-3 align-middle";
    const formattedType = (type === 'Multi') ? 'Multi' : 'Single';

    switch (formattedType) {
      case 'Single':
        return `${baseClasses} bg-blue-100 text-[#0B79D0]`;
      case 'Multi':
        return `${baseClasses} bg-orange-100 text-orange-800`;
      default:
        return `${baseClasses} bg-gray-100 text-gray-800`;
    }
  };

  return (
    <>
      <div className="bg-slate-50 rounded-xl shadow-md w-full flex flex-col flex-grow overflow-hidden">
        {/* ===== HEADER (FIXED) ===== */}
        <div className="flex-shrink-0 p-4 sm:p-6 md:p-8">
          <div className="mb-4 sm:mb-6">
            <p className="text-sm text-gray-500">Frage {currentQuestionIndex + 1} von {questions.length}</p>
            <div className="w-full bg-slate-200 rounded-full h-2.5 mt-2">
              <div className="bg-[#0B79D0] h-2.5 rounded-full" style={{ width: `${((currentQuestionIndex + 1) / questions.length) * 100}%` }}></div>
            </div>
          </div>

          <div className="flex flex-wrap justify-center gap-1 sm:gap-2">
            {questions.map((_, index) => {
              const isAnswered = userAnswers[index] && userAnswers[index].length > 0;
              const isCurrent = index === currentQuestionIndex;

              let buttonClasses = "w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#0B79D0]";

              if (isCurrent) {
                buttonClasses += " bg-[#0B79D0] text-white";
              } else if (isAnswered) {
                buttonClasses += " bg-slate-300 text-slate-800 hover:bg-slate-400";
              } else {
                buttonClasses += " bg-slate-200 text-slate-600 hover:bg-slate-300";
              }

              return (
                <button
                  key={index}
                  onClick={() => setCurrentQuestionIndex(index)}
                  className={buttonClasses}
                  aria-label={`Gehe zu Frage ${index + 1}`}
                >
                  {index + 1}
                </button>
              );
            })}
          </div>
        </div>

        {/* ===== CONTENT (SCROLLABLE) ===== */}
        <div className="flex-grow overflow-y-auto p-4 sm:p-6 md:p-8 border-y border-slate-200">
          {currentQuestion.imageUrl && (
            <div className="mb-4 sm:mb-6">
              <img
                src={currentQuestion.imageUrl}
                alt={`Bild zur Frage: ${currentQuestion.questionText.substring(0, 50)}...`}
                className="w-full max-h-80 object-contain rounded-lg bg-slate-100"
              />
            </div>
          )}

          <div className="p-4 border-2 border-slate-200 rounded-lg bg-white mb-4 sm:mb-6">
            <h2 className="text-lg md:text-xl font-bold text-gray-800 inline whitespace-pre-wrap">{currentQuestion.questionText}</h2>
            <span className={getTypeBadgeClasses(currentQuestion.type)}>
                {currentQuestion.type === 'Multi' ? 'Multi' : 'Single'}
            </span>
          </div>

          <div className="space-y-3 sm:space-y-4">
            {currentQuestion.options.map((option, index) => (
              <button
                key={index}
                onClick={() => onAnswerSelect(currentQuestionIndex, index)}
                className={`w-full text-left p-3 sm:p-4 border-2 rounded-lg transition-all duration-200 text-gray-700 flex items-center
                  ${selectedAnswers.includes(index)
                    ? 'bg-blue-100 border-[#0B79D0] ring-2 ring-[#0B79D0]/50'
                    : 'bg-white border-slate-300 hover:bg-slate-100 hover:border-[#0B79D0]'
                  }`}
              >
                <div className="flex-shrink-0 w-6 h-6 flex items-center justify-center border-2 border-slate-400 rounded-md mr-4">
                  {selectedAnswers.includes(index) && <div className="w-4 h-4 bg-[#0B79D0] rounded-sm"></div>}
                </div>
                <span className={`text-sm sm:text-base font-medium whitespace-pre-wrap ${selectedAnswers.includes(index) ? 'text-[#0B79D0]' : 'text-gray-700'}`}>{option}</span>
              </button>
            ))}
          </div>
        </div>

        {/* ===== FOOTER (FIXED) ===== */}
        <div className="flex-shrink-0 p-4 sm:p-6 md:p-8">
          <div className="flex justify-between items-center">
            <button
              onClick={handlePrev}
              disabled={currentQuestionIndex === 0}
              className="bg-slate-200 text-slate-700 font-bold py-2 px-6 rounded-lg hover:bg-slate-300 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              Zurück
            </button>
            {currentQuestionIndex < questions.length - 1 ? (
              <button
                onClick={handleNext}
                className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors"
              >
                Weiter
              </button>
            ) : (
              <button
                onClick={handleSubmitRequest}
                className="bg-[#0B79D0] text-white font-bold py-2 px-6 rounded-lg hover:bg-[#0968b4] transition-colors"
              >
                Abschicken
              </button>
            )}
          </div>
        </div>
      </div>
      <ConfirmationModal
        isOpen={isConfirmationModalOpen}
        onConfirm={handleConfirmSubmit}
        onCancel={() => setIsConfirmationModalOpen(false)}
      />
    </>
  );
};

export default Quiz;

import React, { useState, useEffect, useCallback } from 'react';
import { fetchAllAccessCodes, createAccessCode, updateAccessCode, deleteAccessCode } from '../services/supabaseService';
import { AccessCode } from '../types';
import ToggleSwitch from './ToggleSwitch';
import KeyIcon from './icons/KeyIcon';
import ClipboardIcon from './icons/ClipboardIcon';
import CheckIcon from './icons/CheckIcon';

const ADJECTIVES = ['SONNIG', 'BLAU', 'SCHNELL', 'KLUG', 'STARK', 'FREI', 'GRÜN', 'SANFT', 'MUTIG', 'LEISE'];
const NOUNS = ['HUND', 'BAUM', 'FLUSS', 'STERN', 'MOND', 'SEE', 'BERG', 'WIND', 'FELS', 'WEG'];

const generateReadableCode = (): string => {
  const randomAdj = ADJECTIVES[Math.floor(Math.random() * ADJECTIVES.length)];
  const randomNoun = NOUNS[Math.floor(Math.random() * NOUNS.length)];
  const randomNumber = Math.floor(Math.random() * 90) + 10;
  return `${randomAdj}-${randomNoun}-${randomNumber}`;
};

const AccessCodeManager: React.FC = () => {
  const [codes, setCodes] = useState<AccessCode[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [studentName, setStudentName] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [copiedCode, setCopiedCode] = useState<string | null>(null);

  const loadCodes = useCallback(async () => {
    setIsLoading(true);
    try {
      const fetchedCodes = await fetchAllAccessCodes();
      setCodes(fetchedCodes);
      setError(null);
    } catch (err: any) {
      setError(err.message || 'Fehler beim Laden der Zugangscodes.');
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    loadCodes();
  }, [loadCodes]);

  const handleGenerateCode = async () => {
    setIsGenerating(true);
    try {
      const newCodeString = generateReadableCode();
      const newCode = await createAccessCode(newCodeString, studentName || null);
      setCodes(prev => [newCode, ...prev]);
      setStudentName('');
      setError(null);
    } catch (err: any) {
      setError(err.message || 'Fehler beim Erstellen des Codes.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleToggleStatus = async (codeToUpdate: AccessCode) => {
    // FIX: Refactored to correctly implement optimistic UI update with proper error handling.
    // The UI is updated immediately for responsiveness.
    setCodes(prev =>
      prev.map(c =>
        c.id === codeToUpdate.id ? { ...c, is_active: !c.is_active } : c,
      ),
    );

    try {
      await updateAccessCode(codeToUpdate.id, { is_active: !codeToUpdate.is_active });
      setError(null);
    } catch (err: any) {
      setError(err.message || 'Fehler beim Aktualisieren des Status.');
      // If the API call fails, revert the UI change to reflect the actual state.
      setCodes(prev =>
        prev.map(c =>
          c.id === codeToUpdate.id
            ? { ...c, is_active: codeToUpdate.is_active }
            : c,
        ),
      );
    }
  };

  const handleDelete = async (id: number) => {
    if (window.confirm('Sind Sie sicher, dass Sie diesen Zugangscode endgültig löschen möchten?')) {
      try {
        await deleteAccessCode(id);
        setCodes(prev => prev.filter(c => c.id !== id));
        setError(null);
      } catch (err: any) {
        setError(err.message || 'Fehler beim Löschen des Codes.');
      }
    }
  };

  const handleCopyToClipboard = (code: string) => {
    navigator.clipboard.writeText(code);
    setCopiedCode(code);
    setTimeout(() => setCopiedCode(null), 2000);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('de-DE', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    });
  };

  return (
    <div className="space-y-8">
      <div className="bg-white p-6 rounded-xl shadow-lg">
        <h2 className="text-xl font-bold text-gray-800 mb-4 inline-flex items-center gap-2"><KeyIcon className="w-6 h-6"/> Neuer Zugangscode</h2>
        <p className="text-sm text-gray-600 mb-4">Erstellen Sie einen neuen, einzigartigen Zugangscode für einen Studenten. Der Name ist optional, hilft aber bei der Zuordnung.</p>
        <div className="flex flex-col sm:flex-row gap-4">
          <input
            type="text"
            value={studentName}
            onChange={(e) => setStudentName(e.target.value)}
            placeholder="Name des Studenten (optional)"
            className="flex-grow p-2 border rounded-lg bg-white text-gray-900 focus:ring-2 focus:ring-[#0B79D0] focus:outline-none"
          />
          <button
            onClick={handleGenerateCode}
            disabled={isGenerating}
            className="bg-green-600 text-white font-bold py-2 px-5 rounded-lg hover:bg-green-700 transition-colors disabled:bg-gray-400"
          >
            {isGenerating ? 'Erstelle...' : 'Code erstellen'}
          </button>
        </div>
      </div>

      <div className="bg-white p-6 rounded-xl shadow-lg">
        <h2 className="text-xl font-bold text-gray-800 mb-4">Bestehende Zugangscodes ({codes.length})</h2>
        {error && <p className="text-red-600 font-semibold mb-4">{error}</p>}
        {isLoading ? (
          <p>Lade Zugangscodes...</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="border-b text-sm text-gray-600">
                  <th className="p-2">Code</th>
                  <th className="p-2">Student</th>
                  <th className="p-2">Erstellt am</th>
                  <th className="p-2">Status</th>
                  <th className="p-2">Aktionen</th>
                </tr>
              </thead>
              <tbody>
                {codes.map(code => (
                  <tr key={code.id} className="border-b text-gray-800 hover:bg-slate-50">
                    <td className="p-2 font-mono">
                      <div className="flex items-center gap-2">
                        {code.code}
                        <button onClick={() => handleCopyToClipboard(code.code)} className="text-slate-400 hover:text-[#0B79D0]">
                          {copiedCode === code.code ? <CheckIcon className="w-4 h-4 text-green-600" /> : <ClipboardIcon className="w-4 h-4" />}
                        </button>
                      </div>
                    </td>
                    <td className="p-2">{code.student_name || <span className="text-gray-400">N/A</span>}</td>
                    <td className="p-2 text-sm text-gray-500">{formatDate(code.created_at)}</td>
                    <td className="p-2">
                       <ToggleSwitch 
                          enabled={code.is_active}
                          onChange={() => handleToggleStatus(code)}
                          ariaLabel={`Zugang für ${code.student_name || code.code} ${code.is_active ? 'deaktivieren' : 'aktivieren'}`}
                       />
                    </td>
                    <td className="p-2">
                      <button onClick={() => handleDelete(code.id)} className="text-red-500 font-semibold">
                        Löschen
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default AccessCodeManager;

import { createClient } from '@supabase/supabase-js';
import { Question, AccessCode } from '../types';
import { SchulhundModuleType } from '../App';

// ===================================================================================
// Liest die Supabase-Zugangsdaten aus den Umgebungsvariablen,
// die in Vercel oder einer lokalen .env-Datei bereitgestellt werden.
// ===================================================================================
export const SUPABASE_URL = process.env.VITE_SUPABASE_URL!; 
export const SUPABASE_KEY = process.env.VITE_SUPABASE_ANON_KEY!;


if (!SUPABASE_URL || !SUPABASE_KEY) {
  console.error("Supabase URL und Key sind nicht konfiguriert. Stellen Sie sicher, dass VITE_SUPABASE_URL und VITE_SUPABASE_ANON_KEY in den Vercel Environment Variables gesetzt sind.");
  // Wir werfen hier keinen Fehler, damit die App nicht abstürzt, aber die Konsole wird eine klare Meldung anzeigen.
}

const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

/**
 * Speichert ein Array von Fragen in der Supabase-Datenbank.
 * @param questions Ein Array von Question-Objekten.
 */
export const saveQuestions = async (questions: Omit<Question, 'id' | 'created_at'>[]): Promise<void> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { error } = await supabase
    .from('questions')
    .insert(questions);

  if (error) {
    console.error('Fehler beim Speichern der Fragen in Supabase:', error);
    throw new Error('Fragen konnten nicht in der Datenbank gespeichert werden.');
  }
};


/**
 * Holt eine zufällige Anzahl von Fragen aus der Supabase-Datenbank.
 * @param count Die Anzahl der zufälligen Fragen, die abgerufen werden sollen.
 * @returns Ein Promise, das zu einem Array von Question-Objekten aufgelöst wird.
 */
export const fetchRandomQuestions = async (count: number, schulhundModule: SchulhundModuleType): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    let query = supabase
        .from('questions')
        .select('*');

    if (schulhundModule === 'hundefuehrerschein') {
      // Schließe die spezielle Kategorie aus
      query = query.not('category', 'eq', 'Spezialthema: Schul-, Therapie- und Besuchshunde');
    } else if (schulhundModule === 'schulhund') {
      // Wähle NUR die spezielle Kategorie aus
      query = query.eq('category', 'Spezialthema: Schul-, Therapie- und Besuchshunde');
    }

    const { data, error } = await query;

    if (error) {
        console.error('Fehler beim Abrufen der Fragen aus Supabase:', error);
        throw new Error('Fragen konnten nicht aus der Datenbank geladen werden.');
    }

    if (!data || data.length === 0) {
        throw new Error(`Keine Fragen in der Datenbank gefunden, die den Kriterien entsprechen.`);
    }

    // Mische das Array und wähle die ersten 'count' Elemente aus.
    const shuffled = data.sort(() => 0.5 - Math.random());
    return shuffled.slice(0, count) as Question[];
};

/**
 * Holt alle Fragen aus der Datenbank.
 */
export const fetchAllQuestions = async (): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .select('*')
        .order('id', { ascending: true });

    if (error) {
        console.error('Fehler beim Abrufen aller Fragen:', error);
        throw new Error('Fragen konnten nicht geladen werden.');
    }
    return data as Question[];
};

/**
 * Erstellt eine neue Frage in der Datenbank.
 */
export const createQuestion = async (question: Omit<Question, 'id' | 'created_at'>): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .insert([question])
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Erstellen der Frage:', error);
        throw new Error('Frage konnte nicht erstellt werden.');
    }
    return data as Question;
};


/**
 * Aktualisiert eine bestehende Frage in der Datenbank.
 */
export const updateQuestion = async (question: Question): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (!question.id) throw new Error("Frage benötigt eine ID zum Aktualisieren.");

    const { id, created_at, ...updateData } = question;

    const { data, error } = await supabase
        .from('questions')
        .update(updateData)
        .eq('id', id)
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Aktualisieren der Frage:', error);
        throw new Error('Frage konnte nicht aktualisiert werden.');
    }
    return data as Question;
};

/**
 * Löscht eine Frage aus der Datenbank.
 */
export const deleteQuestion = async (id: number): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .delete()
        .eq('id', id)
        .select();

    if (error) {
        console.error('Fehler beim Löschen der Frage:', error);
        throw new Error('Frage konnte nicht gelöscht werden.');
    }

    // Wenn RLS den Löschvorgang verhindert, ist der Fehler 'null', aber es werden keine Daten zurückgegeben.
    // Wir prüfen, ob der Löschvorgang tatsächlich erfolgreich war.
    if (!data || data.length === 0) {
      console.error('Löschen der Frage fehlgeschlagen: Zeile nicht gefunden oder keine Berechtigung.');
      throw new Error('Frage konnte nicht gelöscht werden. Möglicherweise fehlt die Berechtigung oder die Frage existiert nicht mehr.');
    }
};

/**
 * Löscht mehrere Fragen auf einmal aus der Datenbank.
 * @param ids Ein Array von IDs der zu löschenden Fragen.
 */
export const deleteMultipleQuestions = async (ids: number[]): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (ids.length === 0) return;

    const { error } = await supabase
        .from('questions')
        .delete()
        .in('id', ids);

    if (error) {
        console.error('Fehler beim Löschen mehrerer Fragen:', error);
        throw new Error('Die ausgewählten Fragen konnten nicht gelöscht werden.');
    }
};


// === ACCESS CODE FUNCTIONS ===

/**
 * Validiert, ob ein Zugangscode existiert und aktiv ist.
 * @param code Der zu validierende Zugangscode.
 * @returns Ein Promise, das bei Gültigkeit zu true, andernfalls zu false aufgelöst wird.
 */
export const validateAccessCode = async (code: string): Promise<boolean> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { data, error } = await supabase
    .from('access_codes')
    .select('id')
    .eq('code', code)
    .eq('is_active', true)
    .single();

  if (error && error.code !== 'PGRST116') { // PGRST116: "Query returned no rows", was für ungültige Codes erwartet wird
    console.error('Fehler bei der Validierung des Zugangscodes:', error);
    return false;
  }

  return !!data;
};

/**
 * Holt alle Zugangscodes aus der Datenbank.
 */
export const fetchAllAccessCodes = async (): Promise<AccessCode[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('access_codes')
        .select('*')
        .order('created_at', { ascending: false });

    if (error) {
        console.error('Fehler beim Abrufen aller Zugangscodes:', error);
        throw new Error('Zugangscodes konnten nicht geladen werden.');
    }
    return data as AccessCode[];
};

/**
 * Erstellt einen neuen Zugangscode in der Datenbank.
 */
export const createAccessCode = async (code: string, studentName?: string | null): Promise<AccessCode> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('access_codes')
        .insert([{ code, student_name: studentName, is_active: true }])
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Erstellen des Zugangscodes:', error);
        throw new Error('Zugangscode konnte nicht erstellt werden.');
    }
    return data as AccessCode;
};

/**
 * Aktualisiert einen bestehenden Zugangscode (z.B. den Aktivierungsstatus oder den Namen).
 */
export const updateAccessCode = async (id: number, updates: Partial<Omit<AccessCode, 'id' | 'created_at' | 'code'>>): Promise<AccessCode> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('access_codes')
        .update(updates)
        .eq('id', id)
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Aktualisieren des Zugangscodes:', error);
        throw new Error('Zugangscode konnte nicht aktualisiert werden.');
    }
    return data as AccessCode;
};

/**
 * Löscht einen Zugangscode aus der Datenbank.
 */
export const deleteAccessCode = async (id: number): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { error } = await supabase
        .from('access_codes')
        .delete()
        .eq('id', id);

    if (error) {
        console.error('Fehler beim Löschen des Zugangscodes:', error);
        throw new Error('Zugangscode konnte nicht gelöscht werden.');
    }
};

// === ADMIN AUTHENTICATION ===

/**
 * Validiert die Anmeldeinformationen des Administrators gegen die Datenbank.
 * @param username Der vom Administrator eingegebene Benutzername.
 * @param password Das vom Administrator eingegebene Passwort.
 * @returns Ein Promise, das bei Gültigkeit zu true, andernfalls zu false aufgelöst wird.
 */
export const validateAdminCredentials = async (username: string, password: string): Promise<boolean> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { data, error } = await supabase
    .from('admin_users')
    .select('id')
    .eq('username', username)
    .eq('password', password) // Direkter Vergleich. Für Produktionsumgebungen wird Hashing empfohlen.
    .single();

  if (error && error.code !== 'PGRST116') { // Ignoriere "no rows" Fehler
    console.error('Fehler bei der Admin-Validierung:', error);
    return false;
  }

  return !!data;
};


// === LEARNING MATERIALS ===

/**
 * Lädt den Studienleitfaden (PDF) in den Supabase Storage hoch.
 * Überschreibt eine vorhandene Datei, um sicherzustellen, dass immer nur die neueste Version verfügbar ist.
 * @param file Die PDF-Datei, die hochgeladen werden soll.
 */
export const uploadLearningGuide = async (file: File): Promise<void> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { data, error } = await supabase.storage
    .from('learning_materials')
    .upload('studienleitfaden.pdf', file, {
      cacheControl: '3600',
      upsert: true, // Überschreibt die Datei, falls sie bereits existiert
    });

  if (error) {
    console.error('Fehler beim Hochladen des Studienleitfadens:', error);
    throw new Error('Der Studienleitfaden konnte nicht hochgeladen werden.');
  }
};

import { createClient } from '@supabase/supabase-js';
import { Question, AccessCode } from '../types';
import { SchulhundModuleType } from '../App';

// ===================================================================================
// Liest die Supabase-Zugangsdaten aus den Umgebungsvariablen.
// In einer Vite-App geschieht dies über `import.meta.env`.
// ===================================================================================
export const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL!; 
export const SUPABASE_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY!;


if (!SUPABASE_URL || !SUPABASE_KEY) {
  console.error("Supabase URL und Key sind nicht konfiguriert. Stellen Sie sicher, dass VITE_SUPABASE_URL und VITE_SUPABASE_ANON_KEY in den Vercel Environment Variables gesetzt sind.");
  // Wir werfen hier keinen Fehler, damit die App nicht abstürzt, aber die Konsole wird eine klare Meldung anzeigen.
}

const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

/**
 * Speichert ein Array von Fragen in der Supabase-Datenbank.
 * @param questions Ein Array von Question-Objekten.
 */
export const saveQuestions = async (questions: Omit<Question, 'id' | 'created_at'>[]): Promise<void> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { error } = await supabase
    .from('questions')
    .insert(questions);

  if (error) {
    console.error('Fehler beim Speichern der Fragen in Supabase:', error);
    throw new Error('Fragen konnten nicht in der Datenbank gespeichert werden.');
  }
};


/**
 * Holt eine zufällige Anzahl von Fragen aus der Supabase-Datenbank.
 * @param count Die Anzahl der zufälligen Fragen, die abgerufen werden sollen.
 * @returns Ein Promise, das zu einem Array von Question-Objekten aufgelöst wird.
 */
export const fetchRandomQuestions = async (count: number, schulhundModule: SchulhundModuleType): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    let query = supabase
        .from('questions')
        .select('*');

    if (schulhundModule === 'hundefuehrerschein') {
      // Schließe die spezielle Kategorie aus
      query = query.not('category', 'eq', 'Spezialthema: Schul-, Therapie- und Besuchshunde');
    } else if (schulhundModule === 'schulhund') {
      // Wähle NUR die spezielle Kategorie aus
      query = query.eq('category', 'Spezialthema: Schul-, Therapie- und Besuchshunde');
    }

    const { data, error } = await query;

    if (error) {
        console.error('Fehler beim Abrufen der Fragen aus Supabase:', error);
        throw new Error('Fragen konnten nicht aus der Datenbank geladen werden.');
    }

    if (!data || data.length === 0) {
        throw new Error(`Keine Fragen in der Datenbank gefunden, die den Kriterien entsprechen.`);
    }

    // Mische das Array und wähle die ersten 'count' Elemente aus.
    const shuffled = data.sort(() => 0.5 - Math.random());
    return shuffled.slice(0, count) as Question[];
};

/**
 * Holt alle Fragen aus der Datenbank.
 */
export const fetchAllQuestions = async (): Promise<Question[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .select('*')
        .order('id', { ascending: true });

    if (error) {
        console.error('Fehler beim Abrufen aller Fragen:', error);
        throw new Error('Fragen konnten nicht geladen werden.');
    }
    return data as Question[];
};

/**
 * Erstellt eine neue Frage in der Datenbank.
 */
export const createQuestion = async (question: Omit<Question, 'id' | 'created_at'>): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .insert([question])
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Erstellen der Frage:', error);
        throw new Error('Frage konnte nicht erstellt werden.');
    }
    return data as Question;
};


/**
 * Aktualisiert eine bestehende Frage in der Datenbank.
 */
export const updateQuestion = async (question: Question): Promise<Question> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (!question.id) throw new Error("Frage benötigt eine ID zum Aktualisieren.");

    const { id, created_at, ...updateData } = question;

    const { data, error } = await supabase
        .from('questions')
        .update(updateData)
        .eq('id', id)
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Aktualisieren der Frage:', error);
        throw new Error('Frage konnte nicht aktualisiert werden.');
    }
    return data as Question;
};

/**
 * Löscht eine Frage aus der Datenbank.
 */
export const deleteQuestion = async (id: number): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('questions')
        .delete()
        .eq('id', id)
        .select();

    if (error) {
        console.error('Fehler beim Löschen der Frage:', error);
        throw new Error('Frage konnte nicht gelöscht werden.');
    }

    // Wenn RLS den Löschvorgang verhindert, ist der Fehler 'null', aber es werden keine Daten zurückgegeben.
    // Wir prüfen, ob der Löschvorgang tatsächlich erfolgreich war.
    if (!data || data.length === 0) {
      console.error('Löschen der Frage fehlgeschlagen: Zeile nicht gefunden oder keine Berechtigung.');
      throw new Error('Frage konnte nicht gelöscht werden. Möglicherweise fehlt die Berechtigung oder die Frage existiert nicht mehr.');
    }
};

/**
 * Löscht mehrere Fragen auf einmal aus der Datenbank.
 * @param ids Ein Array von IDs der zu löschenden Fragen.
 */
export const deleteMultipleQuestions = async (ids: number[]): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");
    if (ids.length === 0) return;

    const { error } = await supabase
        .from('questions')
        .delete()
        .in('id', ids);

    if (error) {
        console.error('Fehler beim Löschen mehrerer Fragen:', error);
        throw new Error('Die ausgewählten Fragen konnten nicht gelöscht werden.');
    }
};


// === ACCESS CODE FUNCTIONS ===

/**
 * Validiert, ob ein Zugangscode existiert und aktiv ist.
 * @param code Der zu validierende Zugangscode.
 * @returns Ein Promise, das bei Gültigkeit zu true, andernfalls zu false aufgelöst wird.
 */
export const validateAccessCode = async (code: string): Promise<boolean> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { data, error } = await supabase
    .from('access_codes')
    .select('id')
    .eq('code', code)
    .eq('is_active', true)
    .single();

  if (error && error.code !== 'PGRST116') { // PGRST116: "Query returned no rows", was für ungültige Codes erwartet wird
    console.error('Fehler bei der Validierung des Zugangscodes:', error);
    return false;
  }

  return !!data;
};

/**
 * Holt alle Zugangscodes aus der Datenbank.
 */
export const fetchAllAccessCodes = async (): Promise<AccessCode[]> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('access_codes')
        .select('*')
        .order('created_at', { ascending: false });

    if (error) {
        console.error('Fehler beim Abrufen aller Zugangscodes:', error);
        throw new Error('Zugangscodes konnten nicht geladen werden.');
    }
    return data as AccessCode[];
};

/**
 * Erstellt einen neuen Zugangscode in der Datenbank.
 */
export const createAccessCode = async (code: string, studentName?: string | null): Promise<AccessCode> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('access_codes')
        .insert([{ code, student_name: studentName, is_active: true }])
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Erstellen des Zugangscodes:', error);
        throw new Error('Zugangscode konnte nicht erstellt werden.');
    }
    return data as AccessCode;
};

/**
 * Aktualisiert einen bestehenden Zugangscode (z.B. den Aktivierungsstatus oder den Namen).
 */
export const updateAccessCode = async (id: number, updates: Partial<Omit<AccessCode, 'id' | 'created_at' | 'code'>>): Promise<AccessCode> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { data, error } = await supabase
        .from('access_codes')
        .update(updates)
        .eq('id', id)
        .select()
        .single();

    if (error) {
        console.error('Fehler beim Aktualisieren des Zugangscodes:', error);
        throw new Error('Zugangscode konnte nicht aktualisiert werden.');
    }
    return data as AccessCode;
};

/**
 * Löscht einen Zugangscode aus der Datenbank.
 */
export const deleteAccessCode = async (id: number): Promise<void> => {
    if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

    const { error } = await supabase
        .from('access_codes')
        .delete()
        .eq('id', id);

    if (error) {
        console.error('Fehler beim Löschen des Zugangscodes:', error);
        throw new Error('Zugangscode konnte nicht gelöscht werden.');
    }
};

// === ADMIN AUTHENTICATION ===

/**
 * Validiert die Anmeldeinformationen des Administrators gegen die Datenbank.
 * @param username Der vom Administrator eingegebene Benutzername.
 * @param password Das vom Administrator eingegebene Passwort.
 * @returns Ein Promise, das bei Gültigkeit zu true, andernfalls zu false aufgelöst wird.
 */
export const validateAdminCredentials = async (username: string, password: string): Promise<boolean> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { data, error } = await supabase
    .from('admin_users')
    .select('id')
    .eq('username', username)
    .eq('password', password) // Direkter Vergleich. Für Produktionsumgebungen wird Hashing empfohlen.
    .single();

  if (error && error.code !== 'PGRST116') { // Ignoriere "no rows" Fehler
    console.error('Fehler bei der Admin-Validierung:', error);
    return false;
  }

  return !!data;
};


// === LEARNING MATERIALS ===

/**
 * Lädt den Studienleitfaden (PDF) in den Supabase Storage hoch.
 * Überschreibt eine vorhandene Datei, um sicherzustellen, dass immer nur die neueste Version verfügbar ist.
 * @param file Die PDF-Datei, die hochgeladen werden soll.
 */
export const uploadLearningGuide = async (file: File): Promise<void> => {
  if (!supabase) throw new Error("Supabase-Client nicht initialisiert.");

  const { data, error } = await supabase.storage
    .from('learning_materials')
    .upload('studienleitfaden.pdf', file, {
      cacheControl: '3600',
      upsert: true, // Überschreibt die Datei, falls sie bereits existiert
    });

  if (error) {
    console.error('Fehler beim Hochladen des Studienleitfadens:', error);
    throw new Error('Der Studienleitfaden konnte nicht hochgeladen werden.');
  }
};

